const entrees: EntreeTaille[] = ENTREES.map(([m, t, z, min, max, p]) => {
  const modele = MODELES[m]!;
  const [volet, sousVolet, genre, source] = META[m]!;
  const zone = ZONES_REF[z]!;
  return {
    marqueId: modele.marqueId,
    modeleId: modele.modeleId,
    versionId: modele.versionId,
    volet,
    sousVolet,
    genre,
    libelleTaille: TAILLES[t]!,
    zone,
    valeurMin: min,
    valeurMax: max,
    unite: zone === "poids" ? "kg" : "cm",
    provenance: PROVENANCES[p]!,
    source,
    dateCollecte: DATE_RELEVE,
    dateDerniereVerification: DATE_RELEVE,
  };
});

export const REFERENTIEL: Referentiel = {
  versionReferentiel: "ref-2026-08-19",
  versionParametres: "par-2026-08-06",
  modeles: [...MODELES, ...LOT2.modeles, ...LOT_SKI.modeles],
  entrees: [...entrees, ...LOT2.entrees, ...LOT_SKI.entrees],
};


/**
 * Seuil d'admission : une marque n'apparaît dans les résultats que si ses
 * données couvrent au minimum les zones critiques du sous-volet concerné
 * (doc 03, §4).
 */
export function marquesAdmises(sousVolet: string): string[] {
  const parMarque = new Map<string, Set<string>>();
  for (const e of REFERENTIEL.entrees) {
    if (e.sousVolet !== sousVolet) continue;
    if (e.provenance === "missing") continue;
    const set = parMarque.get(e.marqueId) ?? new Set<string>();
    set.add(e.zone);
    parMarque.set(e.marqueId, set);
  }
  return [...parMarque.keys()];
}
